package com.bank.spark.model;

// A catalog entry: its kind and whether Spark owns the underlying data.
public class CatalogEntry {
    public enum Kind { TEMP_VIEW, GLOBAL_TEMP_VIEW, MANAGED_TABLE, EXTERNAL_TABLE }

    private final String name;
    private final Kind kind;
    private final boolean sparkOwnsData;   // true only for managed tables

    public CatalogEntry(String name, Kind kind, boolean sparkOwnsData) {
        this.name = name;
        this.kind = kind;
        this.sparkOwnsData = sparkOwnsData;
    }

    public String getName() { return name; }
    public Kind getKind() { return kind; }
    public boolean isSparkOwnsData() { return sparkOwnsData; }
}
