package com.bank.spark.service;

import com.bank.spark.model.CatalogEntry;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Simulates registration scope and drop semantics for views and tables.
public class MiniCatalog {

    private static final Logger log = Logger.getLogger(MiniCatalog.class.getName());
    private final Map<String, CatalogEntry> entries = new LinkedHashMap<>();

    // The qualified name reflects scope: global views live under global_temp.
    public String register(CatalogEntry e) {
        String qualified = (e.getKind() == CatalogEntry.Kind.GLOBAL_TEMP_VIEW)
                ? "global_temp." + e.getName() : e.getName();
        entries.put(qualified, e);
        log.info(() -> "Registered " + e.getKind() + " as '" + qualified + "'");
        return qualified;
    }

    // Drop: deletes data files ONLY for a managed table.
    public void drop(String qualifiedName) {
        CatalogEntry e = entries.remove(qualifiedName);
        if (e == null) { log.warning(() -> "No entry '" + qualifiedName + "'"); return; }
        if (e.isSparkOwnsData()) {
            log.warning(() -> "Dropped MANAGED table '" + qualifiedName + "' → DATA FILES DELETED");
        } else if (e.getKind() == CatalogEntry.Kind.EXTERNAL_TABLE) {
            log.info(() -> "Dropped EXTERNAL table '" + qualifiedName + "' → metadata gone, DATA KEPT");
        } else {
            log.info(() -> "Dropped view '" + qualifiedName + "' → virtual, no data to delete");
        }
    }

    // Visibility across a (simulated) other session.
    public boolean visibleInOtherSession(String qualifiedName) {
        CatalogEntry e = entries.get(qualifiedName);
        if (e == null) return false;
        // Only global temp views (and tables) are visible in another session.
        return e.getKind() != CatalogEntry.Kind.TEMP_VIEW;
    }
}
