package com.bank.spark;

import com.bank.spark.model.CatalogEntry;
import com.bank.spark.service.MiniCatalog;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: scope and drop semantics of views and tables.
public class ViewsTablesDemo {

    private static final Logger log = Logger.getLogger(ViewsTablesDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MiniCatalog catalog = new MiniCatalog();

        String tv = catalog.register(new CatalogEntry("dailyStep", CatalogEntry.Kind.TEMP_VIEW, false));
        String gv = catalog.register(new CatalogEntry("highValue", CatalogEntry.Kind.GLOBAL_TEMP_VIEW, false));
        String mt = catalog.register(new CatalogEntry("scratchAgg", CatalogEntry.Kind.MANAGED_TABLE, true));
        String et = catalog.register(new CatalogEntry("regulatedTxns", CatalogEntry.Kind.EXTERNAL_TABLE, false));

        log.info(() -> "temp view visible in other session? " + catalog.visibleInOtherSession(tv));
        log.info(() -> "global temp view visible in other session? " + catalog.visibleInOtherSession(gv));

        // Drops show the data-deletion difference.
        catalog.drop(mt);   // managed → files deleted
        catalog.drop(et);   // external → files kept
        catalog.drop(tv);   // view → nothing to delete

        log.info("Views and tables demo complete.");
    }
}
